/// <summary>
/// Extension of form MCRHoldCodeTrans
/// </summary>
[ExtensionOf(formdatasourceStr(MCRHoldCodeTrans, MCRHoldCodeTrans))]
final class METMCRHoldCodeTrans_Extension
{
}

Method.Source:
    /// <summary>
    /// initialize the MCRHoldCode record
    /// </summary>
    public void init()
    {
        SalesTable          salesTable = this.formRun().args().record() as SalesTable;
        METSalesOrderTypes  metSalesOrderTypes = METSalesOrderTypes::find(salesTable.METSalesOrderType);

        next init();
      
        if (salesTable.METSalesOrderType)
        {
            MCRHoldCodeTrans    mcrHoldCodeTrans;

            select firstonly mcrHoldCodeTrans
                where mcrHoldCodeTrans.InventRefId == salesTable.SalesId;

            if (!mcrHoldCodeTrans.RecId)
            {
                mcrHoldCodeTrans.INVENTREFID = salesTable.SalesId;
                mcrHoldCodeTrans.MCRHoldCode = metSalesOrderTypes.OrderOnHold;
                mcrHoldCodeTrans.MCRHoldUser = curUserId();
                mcrHoldCodeTrans.doinsert();
            }
            else 
            {
                ttsbegin;
                mcrHoldCodeTrans.selectForUpdate(true);
                mcrHoldCodeTrans.INVENTREFID = salesTable.SalesId;
                mcrHoldCodeTrans.MCRHoldCode = metSalesOrderTypes.OrderOnHold;
                mcrHoldCodeTrans.MCRHoldUser = curUserId();
                mcrHoldCodeTrans.doUpdate();
                ttscommit;
            }
        }
    }
